'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes = n => n > 1e9 ? (n/1024**3).toFixed(2)+' GB' : n > 1e6 ? (n/1024**2).toFixed(1)+' MB' : (n/1024).toFixed(1)+' KB';
let state = {projects:[],sessions:[],skills:[],providers:[]}, currentProject = localStorage.getItem('project') || '', currentSession = localStorage.getItem('session') || '', currentTab='chat', busy=false, editorSave, libraryData={roots:[],models:[]};
let reasoningVisible=false,commandResolving=false,commandOffsets={};
let bootstrapping=true;
let toastTimer, modelRequest=0, modelPreferences={}, availableContext=0;
function logActivity(text,reasoning=false){const log=$('#activity-log');const nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<40;const prefix=reasoning?(reasoningVisible?'':'\nRazonamiento proporcionado por el modelo:\n'):`\n[${new Date().toLocaleTimeString('es-ES')}] `;reasoningVisible=reasoning;log.textContent=(log.textContent+prefix+text).slice(-40000);if($('#activity-follow').checked&&nearBottom)log.scrollTop=log.scrollHeight;}
on('#activity-clear','click',()=>{$('#activity-log').textContent='';});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),7500);}
async function api(path, body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok||data.error)throw Error(data.error||response.statusText);return data;}
function on(selector,event,handler){$(selector).addEventListener(event,e=>Promise.resolve().then(()=>handler(e)).catch(error=>toast(error.message)));}
function openEditor(title,name,content,note,save){$('#editor-title').textContent=title;$('#editor-name').value=name;$('#editor-content').value=content;$('#editor-note').textContent=note;editorSave=save;$('#editor').showModal();}
on('#editor-close','click',()=>$('#editor').close());
on('#editor-form','submit',async e=>{e.preventDefault();await editorSave($('#editor-name').value,$('#editor-content').value);$('#editor').close();await refresh();});
async function refresh(){state=await api('/api/state');if(currentProject&&!state.projects.some(p=>p.id===currentProject))currentProject='';if(currentSession&&!state.sessions.some(s=>s.id===currentSession))currentSession='';renderSidebar();if(currentTab==='chat')await loadInspector();}
function renderSidebar(){
 $('#project-select').innerHTML='<option value="">Todas las conversaciones</option>'+state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#project-select').value=currentProject;
 const sessions=state.sessions.filter(s=>!currentProject||s.project_id===currentProject);$('#sessions').innerHTML=sessions.map(s=>`<button class="session ${s.id===currentSession?'active':''}" data-session="${esc(s.id)}">${esc(s.title)}<small>${esc(state.projects.find(p=>p.id===s.project_id)?.name||'Conversación libre')}</small></button>`).join('')||'<p class="small">Aquí aparecerán tus conversaciones.</p>';
 $('#breadcrumb').textContent=state.projects.find(p=>p.id===currentProject)?.name||'Tu espacio de trabajo';$('#project-info').textContent=state.projects.find(p=>p.id===currentProject)?.instructions|| (currentProject?'Este proyecto aún no tiene instrucciones.':'Selecciona un proyecto para habilitar archivos y herramientas.');
 const cfg=state.projects.find(p=>p.id===currentProject)?.config;$('#workspace-settings').disabled=!currentProject;$('#extension-settings').disabled=!currentProject;$('#workspace-summary').textContent=cfg?`${cfg.root||'Carpeta interna del proyecto'} · Escritura: ${{deny:'denegada',review:'revisión',allow:'permitida'}[cfg.write]} · Ejecución: ${{deny:'denegada',review:'revisión',allow:'permitida'}[cfg.execute]} · Herramientas: listar, leer, buscar, archivos y terminal según permisos.`:'';
 $('#edit-project').disabled=!currentProject;$('#agent').disabled=!currentProject;if(!currentProject)$('#agent').checked=false;
 localStorage.setItem('project',currentProject);localStorage.setItem('session',currentSession);if(!bootstrapping)api('/api/workspace',{project:currentProject,session:currentSession}).catch(()=>{});
}
on('#sessions','click',async e=>{const b=e.target.closest('[data-session]');if(!b||busy)return;currentSession=b.dataset.session;currentProject=state.sessions.find(s=>s.id===currentSession)?.project_id||'';renderSidebar();await loadMessages();await loadInspector();});
on('#project-select','change',async()=>{if(busy)throw Error('Espera a que termine la respuesta.');currentProject=$('#project-select').value;currentSession=state.sessions.find(s=>s.project_id===currentProject)?.id||'';renderSidebar();await loadMessages();await loadInspector();});
on('#new-project','click',()=>openEditor('Nuevo proyecto','','','Las instrucciones se aplican a las conversaciones de este proyecto.',async(name,instructions)=>{const p=await api('/api/projects',{name,instructions});currentProject=p.id;currentSession='';await loadMessages();}));
on('#edit-project','click',()=>{const p=state.projects.find(p=>p.id===currentProject);if(p)openEditor('Instrucciones del proyecto',p.name,p.instructions,'Solo afecta a este espacio.',(name,instructions)=>api('/api/projects',{id:p.id,name,instructions}));});
async function newSession(){const s=await api('/api/sessions',{project_id:currentProject});currentSession=s.id;await refresh();await loadMessages();}
on('#new-chat','click',()=>{if(busy)throw Error('Espera a que termine la respuesta.');return newSession();});
function message(role,content,meta){const item=document.createElement('article');item.className='message '+role;const label=document.createElement('div');label.className='message-label';label.textContent=role==='user'?'TÚ':'AGENTIC STUDIO';const body=document.createElement('div');body.className='message-body';body.textContent=content;item.append(label,body);if(meta&&meta.model){const details=document.createElement('div');details.className='message-meta';details.textContent=`${meta.model} · ${meta.seconds??'—'} s${meta.usage?.completion_tokens?' · '+meta.usage.completion_tokens+' tokens':''}${meta.context?.compacted?' · contexto compactado':''}`;item.append(details);}$('#messages').append(item);return body;}
async function loadMessages(){if(!currentSession){$('#messages').innerHTML=welcomeMarkup;return;}const [messages,events]=await Promise.all([api('/api/messages?session='+encodeURIComponent(currentSession)),api('/api/tool-events?session='+encodeURIComponent(currentSession))]);$('#messages').innerHTML='';if(!messages.length)$('#messages').innerHTML='<div class="empty">Tu espacio está listo. Escribe para empezar.</div>';let index=0;for(const m of messages){while(index<events.length&&events[index].created<m.created){const event=events[index++],item=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');item.className='tool-event';summary.textContent='↳ '+event.name;pre.textContent=JSON.stringify({arguments:JSON.parse(event.arguments),result:JSON.parse(event.result)},null,2).slice(0,14000);item.append(summary,pre);$('#messages').append(item);}message(m.role,m.content,JSON.parse(m.meta));}if(messages.length)finalGenerationStats(JSON.parse(messages[messages.length-1].meta));scrollMessages();}
const welcomeMarkup=$('#messages').innerHTML;
function scrollMessages(){$('#messages').scrollTop=$('#messages').scrollHeight;}
async function refreshModels(restore=true){const cloud=$('#provider').value==='openai-oauth';$('#temperature').disabled=cloud;$('#sampling-panel').classList.toggle('hidden',cloud);$('.local-badge').textContent=cloud?'● OPENAI · NUBE':'● LOCAL';const rid=++modelRequest,pid=$('#provider').value;$('#model').innerHTML='<option value="">Consultando…</option>';try{const data=await api('/api/models?provider='+encodeURIComponent(pid));if(rid!==modelRequest)return;$('#model').innerHTML=data.models.map(m=>`<option value="${esc(m.id)}">${esc(m.id)}</option>`).join('')||'<option value="">Sin modelos disponibles</option>';const remembered=state.selected_models?.[pid];if(restore&&remembered&&data.models.some(m=>m.id===remembered))$('#model').value=remembered;availableContext=data.effective_context||0;$('#context-max').classList.toggle('hidden',!availableContext);$('#context-max').textContent=availableContext?'Máx. '+availableContext.toLocaleString(): 'Usar máximo';modelPreferences=data.preferences||{};const prefs=modelPreferences[$('#model').value];applySampling(prefs?.sampling,data.sampling_extensions);if(prefs){$('#context').value=prefs.context||16384;$('#max-tokens').value=prefs.max_tokens||1024;$('#temperature').value=prefs.temperature??.4;}$('#agent-status').textContent=data.models.length?'Motor conectado · selecciona conversación o crea un proyecto':'Motor conectado sin modelos.';}catch(error){if(rid!==modelRequest)return;$('#model').innerHTML='<option value="">Motor desconectado</option>';$('#agent-status').textContent=error.message;}}
function renderProviders(){const old=$('#provider').value;$('#provider').innerHTML=state.providers.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#provider').value=old||state.selected_provider||state.providers[0]?.id;}
on('#provider','change',()=>refreshModels());on('#refresh-models','click',()=>refreshModels());
function getSampling(){return Object.fromEntries([...document.querySelectorAll('[data-sampling]')].filter(el=>!el.disabled&&el.value!=='').map(el=>[el.dataset.sampling,+el.value]));}
function applySampling(prefs,extensions=true){for(const input of document.querySelectorAll('[data-sampling]')){input.value=prefs?.[input.dataset.sampling]??'';input.disabled=input.hasAttribute('data-extension')&&!extensions;}}
on('#reset-sampling','click',async()=>{applySampling({});await savePrefs();});
async function savePrefs(){if(!$('#model').value)return;await api('/api/preferences',{provider:$('#provider').value,model:$('#model').value,context:+$('#context').value,max_tokens:+$('#max-tokens').value,temperature:+$('#temperature').value,sampling:getSampling()});}
for(const s of ['#context','#max-tokens','#temperature'])on(s,'change',savePrefs);for(const input of document.querySelectorAll('[data-sampling]'))input.addEventListener('change',()=>savePrefs().catch(e=>toast(e.message)));
on('#context-max','click',async()=>{if(availableContext){$('#context').value=availableContext;await savePrefs();toast('Presupuesto ajustado al contexto efectivo del servidor.');}});
on('#model','change',async()=>{const prefs=modelPreferences[$('#model').value]||{};applySampling(prefs.sampling,$('#provider').value==='own'||$('#provider').value==='llama');$('#context').value=prefs.context||16384;$('#max-tokens').value=prefs.max_tokens||1024;$('#temperature').value=prefs.temperature??.4;await savePrefs();});
let liveGeneration=null;
function finalGenerationStats(meta){if(!meta?.model)return;const total=meta.usage_totals?.reported_steps?meta.usage_totals:meta.usage||{},tokens=total.completion_tokens;const parts=[meta.waiting?'Esperando aprobación':'Completado',`${meta.seconds??'—'} s`];if(tokens!==undefined){parts.push(`${tokens.toLocaleString()} tokens de salida`);if(meta.seconds>0)parts.push(`${(tokens/meta.seconds).toFixed(1)} tok/s de media`);}const first=meta.usage?._studio?.first_token_seconds;if(first!==null&&first!==undefined)parts.push(`primer token del paso ${first.toFixed(2)} s`);if(meta.context?.estimated)parts.push(`${meta.context.exact?'':'≈ '}${meta.context.estimated.toLocaleString()} tokens de contexto`);$('#generation-stats').textContent=parts.join(' · ');}
function paintLiveStats(){if(!liveGeneration)return;const g=liveGeneration,seconds=(performance.now()-g.started)/1000,estimated=Math.ceil(g.bytes/4),tokens=g.tokens??estimated,approx=g.tokens===undefined?'≈ ':'';const parts=['Generando',seconds.toFixed(1)+' s',g.characters.toLocaleString()+' caracteres',approx+tokens.toLocaleString()+' tokens de salida del paso'];if(seconds>0&&tokens)parts.push(approx+(tokens/seconds).toFixed(1)+' tok/s de media');if(g.firstText!==undefined)parts.push('primer texto '+g.firstText.toFixed(2)+' s');if(g.phase)parts.push(g.phase);$('#generation-stats').textContent=parts.join(' · ');}
async function send(resume=false){if(busy)return;if(!resume&&!$('#prompt').value.trim())return;if(!$('#model').value&&!resume)throw Error('Conecta un modelo antes de enviar.');if(!currentSession)await newSession();const text=$('#prompt').value;if(!resume){$('#prompt').value='';if($('.empty')||$('.welcome'))$('#messages').innerHTML='';message('user',text);}const target=message('assistant','');busy=true;$('#send').disabled=true;$('#stop').classList.remove('hidden');$('#agent-status').textContent='Preparando contexto…';logActivity('Iniciando '+(resume?'reanudación':'generación')+'. Razonamiento: se mostrará si el motor lo proporciona.');let finalError;liveGeneration={started:performance.now(),bytes:0,characters:0};paintLiveStats();const statsTimer=setInterval(paintLiveStats,250);
 try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(resume?{session_id:currentSession,resume:true}:{session_id:currentSession,message:text,provider:$('#provider').value,model:$('#model').value,agent:$('#agent').checked,retrieval:$('#retrieval').checked,max_tokens:+$('#max-tokens').value,context:+$('#context').value,temperature:+$('#temperature').value,max_steps:+$('#steps').value,sampling:getSampling()})});if(!response.ok)throw Error((await response.json()).error);const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
 const event=ev=>{if(ev.type==='reasoning'){logActivity(ev.text,true);return;}if(ev.type==='tool_start')logActivity('Iniciando '+ev.name+' · '+JSON.stringify(ev.arguments).slice(0,2000));else if(ev.type==='tool')logActivity('Resultado '+ev.name+' · '+JSON.stringify(ev.result).slice(0,6000));else if(ev.type==='activity')logActivity(ev.text);else if(ev.type==='error')logActivity('ERROR · '+ev.error);else if(ev.type==='context')logActivity('Contexto: '+ev.estimated+' / '+ev.budget+(ev.compacted?' · memoria compactada':''));else if(ev.type==='sources')logActivity('Archivos consultados: '+ev.sources.map(s=>s.path).join(', '));else if(ev.type==='waiting')logActivity('Esperando tu decisión sobre las acciones pendientes.');else if(ev.type==='done')logActivity('Tarea finalizada.');if(ev.type==='delta'){target.textContent+=ev.text;if(liveGeneration){liveGeneration.characters+=[...ev.text].length;liveGeneration.bytes+=new TextEncoder().encode(ev.text).length;if(liveGeneration.firstText===undefined)liveGeneration.firstText=(performance.now()-liveGeneration.started)/1000;paintLiveStats();}scrollMessages();}else if(ev.type==='error'){finalError=ev.error;target.textContent+='\n'+ev.error;toast(ev.error);}else if(ev.type==='activity'){$('#agent-status').textContent=ev.text;if(liveGeneration){liveGeneration.phase=ev.text;if(ev.text.startsWith('Paso ')){liveGeneration.bytes=0;liveGeneration.characters=0;liveGeneration.tokens=undefined;}}}else if(ev.type==='metrics'){if(liveGeneration&&ev.usage?.completion_tokens!==undefined)liveGeneration.tokens=ev.usage.completion_tokens;paintLiveStats();}else if(ev.type==='context'){$('#context-meter').textContent=`${ev.exact?'':'≈ '}${ev.estimated.toLocaleString()} / ${ev.budget.toLocaleString()} tokens de entrada${ev.compacted?' · compactado':''}`;}else if(ev.type==='sources'&&ev.sources.length){$('#agent-status').textContent='Consultando '+ev.sources.map(s=>s.path).join(', ');}else if(ev.type==='tool'){const item=document.createElement('details');item.className='tool-event';const summary=document.createElement('summary');summary.textContent='↳ '+ev.name;const pre=document.createElement('pre');pre.textContent=JSON.stringify(ev.result,null,2);item.append(summary,pre);target.parentElement.append(item);$('#agent-status').textContent='Herramienta: '+ev.name;}else if(ev.type==='done'){finalGenerationStats(ev.meta);if(liveGeneration)liveGeneration.final=ev.meta;$('#agent-status').textContent=`Completado en ${ev.meta.seconds} s · ${ev.meta.usage?.completion_tokens||'—'} tokens`;}else if(ev.type==='waiting'){$('#agent-status').textContent='Esperando tu revisión en Acciones del agente.';if(liveGeneration)liveGeneration.final=ev.meta;finalGenerationStats(ev.meta);}};
 while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let i;while((i=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,i);buffer=buffer.slice(i+1);if(line.trim())event(JSON.parse(line));}}buffer+=decoder.decode();if(buffer.trim())event(JSON.parse(buffer));
 }finally{clearInterval(statsTimer);if(liveGeneration?.final)finalGenerationStats(liveGeneration.final);else $('#generation-stats').textContent=finalError?'Error · generación detenida':'Generación interrumpida';liveGeneration=null;busy=false;$('#send').disabled=false;$('#stop').classList.add('hidden');await refresh();if(!finalError)await loadMessages();}}
on('#composer','submit',e=>{e.preventDefault();return send();});on('#prompt','keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();return send();}});on('#stop','click',()=>api('/api/cancel',{}));on('#resume','click',()=>send(true));
on('#export-chat','click',async()=>{if(!currentSession)throw Error('Abre una conversación.');const data=await api('/api/export?session='+encodeURIComponent(currentSession));const text='# '+data.session.title+'\n\n'+data.messages.map(m=>'## '+(m.role==='user'?'Usuario':'Asistente')+'\n\n'+m.content).join('\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));a.download='conversacion.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
async function loadFiles(search=''){if(!currentProject){$('#files').innerHTML='<p class="small">Sin proyecto seleccionado.</p>';return;}if(search){const data=await api('/api/search?project='+encodeURIComponent(currentProject)+'&q='+encodeURIComponent(search));$('#files').innerHTML=data.map(f=>`<div class="file-row"><button data-file="${esc(f.path)}">${esc(f.path)}:${f.line}</button><small>${f.score} coincid.</small></div>`).join('')||'<p class="small">Sin coincidencias.</p>';}else{const data=await api('/api/files?project='+encodeURIComponent(currentProject));$('#files').innerHTML=data.map(f=>`<div class="file-row"><button data-file="${esc(f.path)}">▤ ${esc(f.path)}</button><small>${bytes(f.bytes)}</small></div>`).join('')||'<p class="small">Añade tu primer archivo.</p>';}}
async function loadInspector(){await loadFiles();$('#resume').classList.add('hidden');$('#memory').textContent='Sin compactación necesaria.';if(!currentSession){$('#proposals').innerHTML='<p class="muted">Las propuestas aparecerán aquí antes de aplicarse.</p>';return;}const data=await api('/api/proposals?session='+encodeURIComponent(currentSession));let html='';for(const x of data.extensions||[]){html+=`<div class="proposal"><span class="chip">${esc(x.status)}</span><b>${esc(x.name)}</b><pre>${esc(JSON.stringify(JSON.parse(x.arguments),null,2))}</pre>${x.status==='pending'?`<p class="warning">Acción externa del proyecto. Revisa herramienta, destino y argumentos completos.</p><button class="primary" data-approve="${esc(x.id)}" data-kind="extension">Aprobar acción</button><button data-reject="${esc(x.id)}" data-kind="extension">Rechazar</button>`:`<details><summary>Resultado</summary><pre>${esc(x.result)}</pre></details>`}</div>`;}for(const p of data.files){html+=`<div class="proposal"><span class="chip ${p.status==='pending'?'':'off'}">${esc(p.status)}</span><b>▤ ${esc(p.path)}</b><details><summary>Revisar contenido completo</summary><pre>${esc(p.content)}</pre></details>${p.status==='pending'?`<button data-approve="${esc(p.id)}" data-kind="file" class="primary">Aplicar archivo</button><button data-reject="${esc(p.id)}" data-kind="file">Rechazar</button>`:''}</div>`;}for(const c of data.commands){html+=`<div class="proposal"><span class="chip ${c.status==='pending'?'':'off'}">${esc(c.status)}</span><b>Terminal en el proyecto</b><pre>${esc(c.command)}</pre>${c.status==='pending'?`${c.output?`<p class="warning">${esc(c.output)} ¿Quieres reintentar o rechazar esta acción?</p>`:''}<p class="warning">Se ejecutará aislado en la carpeta autorizada. Revisa el comando completo; puede modificar sus archivos según los permisos.</p><button data-approve="${esc(c.id)}" data-kind="command" class="primary">Ejecutar comando</button><button data-reject="${esc(c.id)}" data-kind="command">Rechazar</button>`:`<details><summary>Resultado</summary><pre>${esc(c.output)}</pre></details>`}</div>`;}$('#proposals').innerHTML=html||'<p class="muted">Ninguna acción pendiente.</p>';if(data.run?.status==='waiting'){$('#resume').classList.remove('hidden');$('#resume').disabled=[...data.files,...data.commands,...(data.extensions||[])].some(p=>p.status==='pending');}if(data.memory)$('#memory').textContent=data.memory.summary;}
on('#proposals','click',async e=>{const b=e.target.closest('[data-approve],[data-reject]');if(!b)return;b.disabled=true;try{const approve=Boolean(b.dataset.approve);if(approve&&b.dataset.kind==='command'&&!confirm('¿Ejecutar este comando exacto con tus permisos? Revisa el texto de la tarjeta antes de aceptar.'))return;logActivity((approve?'Aprobación':'Rechazo')+' del usuario · '+b.dataset.kind);commandResolving=approve&&b.dataset.kind==='command';const result=await api(b.dataset.kind==='file'?'/api/proposal/resolve':b.dataset.kind==='extension'?'/api/extension/resolve':'/api/command/resolve',{id:b.dataset.approve||b.dataset.reject,approve});if(result.output)logActivity('Terminal · '+result.output);logActivity('Acción resuelta · '+b.dataset.kind);await loadInspector();}catch(error){logActivity(error.message);if(error.message.includes('Aislamiento'))alert(error.message+'\n¿Quieres reintentar más tarde o rechazar la acción? Usa los botones de la tarjeta.');throw error;}finally{commandResolving=false;b.disabled=false;}});
on('#files','click',async e=>{const b=e.target.closest('[data-file]');if(!b)return;const name=b.dataset.file;const data=await api('/api/file?project='+encodeURIComponent(currentProject)+'&path='+encodeURIComponent(name));openEditor('Archivo del proyecto',name,data.content,'Se guardará únicamente en este proyecto.',(path,content)=>api('/api/file',{project:currentProject,path,content}));});
on('#add-file','click',()=>{if(!currentProject)throw Error('Crea o selecciona un proyecto.');openEditor('Nuevo archivo','','','Texto UTF-8. Máximo 2 MB.',(path,content)=>api('/api/file',{project:currentProject,path,content}));});
on('#upload-button','click',()=>{if(!currentProject)throw Error('Crea o selecciona un proyecto.');$('#upload').click();});on('#upload','change',async()=>{for(const file of $('#upload').files){if(file.size>2000000)throw Error(file.name+' supera 2 MB.');const buffer=await file.arrayBuffer();let content;try{content=new TextDecoder('utf-8',{fatal:true}).decode(buffer);if(content.includes('\0'))throw Error();}catch{throw Error('Solo texto UTF-8. No se admite este archivo: '+file.name);}const existing=await api('/api/files?project='+encodeURIComponent(currentProject));if(existing.some(f=>f.path===file.name)&&!confirm('¿Sobrescribir '+file.name+'?'))continue;await api('/api/file',{project:currentProject,path:file.name,content});}$('#upload').value='';await loadFiles();});
let searchTimer;on('#file-search','input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadFiles($('#file-search').value).catch(e=>toast(e.message)),250);});
on('#nav','click',async e=>{const b=e.target.closest('[data-tab]');if(!b)return;currentTab=b.dataset.tab;document.querySelectorAll('.tab').forEach(el=>el.classList.toggle('active',el.id===currentTab+'-tab'));document.querySelectorAll('#nav button').forEach(el=>el.classList.toggle('active',el===b));await renderTab();});
on('#global-stop','click',async()=>{const data=await api('/api/memory/reclaim',{});window.webkit?.messageHandlers?.studio?.postMessage({action:'release'});await refresh();if(currentTab==='engine')await renderEngine();await updateResources();toast('Modelo, adaptadores y red local detenidos; descargas canceladas conservando parciales. Memoria propia liberada.');});
on('#quit-app','click',async()=>{if(currentTab==='engine')await persistEngineProfile();await api('/api/memory/reclaim',{});if(window.webkit?.messageHandlers?.studio)window.webkit.messageHandlers.studio.postMessage({action:'quit'});else toast('Motor detenido. Puedes cerrar esta ventana del navegador.');});
const pageTop=(eyebrow,title,description,action='')=>`<div class="page-top"><div><span class="eyebrow subtle">${eyebrow}</span><h2>${title}</h2><p>${description}</p></div>${action}</div>`;
async function renderTab(){if(currentTab==='models')await renderModels();else if(currentTab==='engine')await renderEngine();else if(currentTab==='skills')renderSkills();else if(currentTab==='connections')renderConnections();else if(currentTab==='activity')await renderActivity();else await loadInspector();}
async function renderModels(){libraryData=await api('/api/library');$('#models-tab').innerHTML=pageTop('BIBLIOTECA LOCAL','Un lugar para tus modelos.','Indexa tus carpetas GGUF y Safetensors sin copiar pesos ni cargarlos en RAM. Los modelos MLX se usan a través de su servidor compatible.', '<button id="scan-models">↻ Reindexar</button>')+`<div class="card"><label>Carpetas de modelos · una ruta absoluta por línea<textarea id="model-roots" rows="2" placeholder="/path/to/storage/Modelos">${esc(libraryData.roots.join('\n'))}</textarea></label><button id="save-roots" class="primary">Indexar carpetas</button></div><table><thead><tr><th>MODELO</th><th>FORMATO</th><th>PESOS EN DISCO</th><th>CONTEXTO GUARDADO</th><th></th></tr></thead><tbody>${libraryData.models.map((m,i)=>`<tr><td>${esc(m.name)}<small>${esc(m.path)}</small></td><td><span class="chip">${esc(m.format)}</span></td><td>${bytes(m.bytes)}</td><td>${m.context.toLocaleString()}</td><td>${m.format==='GGUF'?`<button data-load-model="${i}">Configurar carga →</button>`:'Servidor externo'}</td></tr>`).join('')}</tbody></table>${libraryData.models.length?'':'<div class="empty">Añade una carpeta para descubrir modelos locales.</div>'}`;
 $('#models-tab').insertAdjacentHTML('afterbegin','<div id="hub-panel" class="card"></div>');await renderHub();
 on('#save-roots','click',async()=>{await api('/api/library',{roots:$('#model-roots').value.split('\n').map(s=>s.trim()).filter(Boolean)});await renderModels();});on('#scan-models','click',renderModels);
}
on('#models-tab','click',async e=>{const b=e.target.closest('[data-load-model]');if(!b)return;const model=libraryData.models[+b.dataset.loadModel];localStorage.setItem('engine-model',model.path);localStorage.setItem('engine-model:llama',model.path);localStorage.setItem('engine-kind','llama');localStorage.setItem('engine-context',model.context);currentTab='engine';document.querySelector('[data-tab="engine"]').click();});
async function persistEngineProfile(kind){if(!$('#engine-model')?.value)return;return api('/api/engine/profile',{engine:kind||$('#engine-kind').value,model:$('#engine-model').value,binary:$('#engine-binary')?.value,context:+$('#engine-context').value,kv:$('#engine-kv').value,memory_gb:+($('#engine-memory')?.value||8),threads:+($('#engine-threads')?.value||8),batch:+($('#engine-batch')?.value||256),ubatch:+($('#engine-ubatch')?.value||128),gpu_layers:+($('#engine-gpu-layers')?.value??-1),mmap:$('#engine-mmap')?.value!=='no',cpu:$('#engine-cpu')?.value==='cpu',prefill_priority:$('#engine-priority')?.value||'context',moe_cpu_layers:+($('#moe-cpu-layers')?.value||0),moe_cache_mib:+($('#moe-cache')?.value||0),moe_offload:$('#moe-offload')?.checked||false,moe_fraction:+($('#moe-fraction')?.value||.25)});}
let engineRenderRequest=0;
function updateMoePanel(model,kind){const panel=$('#moe-panel');if(!panel)return;const info=model?.moe;if(!info){panel.innerHTML='';return;}const profile=model.profile||{};panel.innerHTML=`<details open><summary>Modelo MoE · ${info.experts} expertos · ${info.active??'—'} activos por token</summary><div class="info-box">Pesos completos: ${bytes(info.weights_bytes)}. Los expertos activos reducen cálculo, no implican cargar solo esa fracción de pesos. Se conserva el enrutamiento del modelo. Las opciones de descarga requieren validación con este modelo; no se han cargado MoE grandes adicionales.</div>${kind==='llama'?`<div class="form-grid"><label>Capas con expertos en CPU<input id="moe-cpu-layers" type="number" min="0" max="512" value="${profile.moe_cpu_layers||0}"></label><label>Caché GPU de expertos (MiB)<input id="moe-cache" type="number" min="0" max="8192" value="${profile.moe_cache_mib||0}"></label></div><p class="small">En Apple Silicon CPU y GPU comparten RAM. Esta opción cambia dónde se ejecutan los expertos; no promete ahorrar el tamaño completo de sus pesos.</p>`:kind==='omlx'?`<label class="toggle"><input id="moe-offload" type="checkbox" ${profile.moe_offload?'checked':''} ${model.moe_offload_supported?'':'disabled'}> Streaming de expertos desde el checkpoint · experimental</label><label>Fracción residente solicitada<input id="moe-fraction" type="number" min="0.05" max="1" step="0.05" value="${profile.moe_fraction||.25}" ${model.moe_offload_supported?'':'disabled'}></label><p class="small">${model.moe_offload_supported?'Disposición de expertos verificada en el checkpoint. El motor mantiene al menos los expertos requeridos por su enrutamiento; puede reducir memoria a costa de velocidad.':'No se ha podido verificar el streaming de expertos para este checkpoint; se mantiene desactivado.'} La admisión del panel sigue presupuestando los pesos completos de forma conservadora.</p>`:'<p class="small">vLLM Metal: pesos completos, una secuencia y KV acotada al contexto. No se altera el número de expertos activos ni se aplica un offload experimental no verificado.</p>'}</details>`;}
async function renderEngine(requestedKind){
 const renderRequest=++engineRenderRequest;
 $('#engine-tab').innerHTML=pageTop('INFERENCIA Y MEMORIA','Consultando el motor…','Comprobando modelos compatibles sin cargar sus pesos.')+'<div class="info-box">La primera consulta de un registro puede tardar unos segundos. Los controles de carga se habilitan al terminar.</div>';

 const engine=await api('/api/engine'),res=await api('/api/resources');
 const kind=requestedKind||engine.engine||localStorage.getItem('engine-kind')||state.engine_config?.engine||'llama';
 const catalog=await api('/api/engine-models?engine='+encodeURIComponent(kind));if(renderRequest!==engineRenderRequest)return;
 const remembered=localStorage.getItem('engine-model:'+kind)||(state.engine_config?.engine===kind?state.engine_config.model:'')||(kind==='llama'?localStorage.getItem('engine-model'):'')||'';
 const selected=catalog.models.find(m=>m.path===(engine.engine===kind?engine.model:remembered));
 const names={llama:'llama.cpp · GGUF',vllm:'vLLM Metal · MLX / Safetensors',omlx:'oMLX · MLX / Safetensors'};
 $('#engine-tab').innerHTML=pageTop('INFERENCIA Y MEMORIA','Tus motores. Un solo espacio.','Selecciona el motor y uno de sus modelos compatibles en las carpetas compartidas. Solo se mantiene un motor propio cargado; los servidores externos siguen bajo tu control.')+
 `<div class="stat-grid"><div class="stat"><b>${engine.running?engine.verified_inference?'Verificado':engine.ready?'API disponible':'Iniciando':'Detenido'}</b><span>${esc(engine.engine?names[engine.engine]:'Motor propio')}${engine.pid?' · PID '+engine.pid:''}</span></div><div class="stat"><b>${res.engine_rss_mb?res.engine_rss_mb+' MB':'—'}</b><span>RSS del proceso principal del motor</span></div><div class="stat"><b>${res.app_rss_mb??'—'} MB</b><span>Backend · ${res.physical_gb??'—'} GB físicos</span></div></div>
 <div class="info-box">${engine.effective_context?'Contexto efectivo comunicado o acotado por la política del motor: '+engine.effective_context.toLocaleString()+' tokens. ':''}Una inferencia activa, archivos sin duplicar y cachés limitadas. La compatibilidad del catálogo comprueba formato, registro y archivos; la carga real se valida al iniciar.</div>
 <div class="card"><h3>Configurar motor propio</h3><div class="form-grid">
 <label class="full">Motor<select id="engine-kind">${Object.entries(names).map(([id,name])=>`<option value="${id}" ${id===kind?'selected':''} ${catalog.runtimes[id]?.installed?'':'disabled'}>${name}${catalog.runtimes[id]?.installed?'':' · no instalado'}</option>`).join('')}</select></label>
 <label class="full">Modelo compatible · ${catalog.models.length} disponibles<select id="engine-model-select"><option value="">Selecciona un modelo…</option>${catalog.models.map(m=>`<option value="${esc(m.path)}" ${m.path===selected?.path?'selected':''}>${esc(m.name)} · ${bytes(m.bytes)}${m.architecture?' · '+esc(m.architecture):''}</option>`).join('')}</select></label>
 <label class="full">Ruta del modelo<input id="engine-model" value="${esc(selected?.path||'')}" readonly></label>
 ${kind==='llama'?`<label class="full">Ejecutable llama-server<input id="engine-binary" value="${esc(localStorage.getItem('engine-binary')||state.engine_config?.binary||'/path/to/storage/Llama/optimizacion-m4-pro/bin/llama-server')}"></label>`:''}
 <label>Contexto total<input id="engine-context" type="number" min="512" max="131072" step="512" value="${engine.engine===kind?engine.context:selected?.context||4096}"></label>
 <label>Precisión de caché KV<select id="engine-kv">${kind==='llama'?'<option value="q8_0">Q8 · equilibrio recomendado</option><option value="q4_0">Q4 · menor memoria, menor precisión</option><option value="f16">F16 · máxima precisión</option>':(kind==='omlx'?'<option value="f16">Nativa sin compresión</option><option value="tq8">TurboQuant 8 bits</option><option value="tq6">TurboQuant 6 bits</option><option value="tq4">TurboQuant 4 bits</option>':'<option value="f16">Nativa · perfil de este motor</option>')}</select></label>
 ${kind==='llama'?'<label>Dispositivo<select id="engine-cpu"><option value="gpu">Metal · selección automática</option><option value="cpu">Solo CPU</option></select></label>':'<label>Límite / presupuesto de memoria (GB)<input id="engine-memory" type="number" min="1" max="128" value="'+(state.engine_config?.engine===kind?state.engine_config.memory_gb||8:8)+'"></label>'}
 </div><details><summary>Configuración avanzada del motor y modelo</summary><div class="form-grid">${kind==='llama'?`<label>Hilos CPU<input id="engine-threads" type="number" min="1" max="64" value="${selected?.profile?.threads||8}"></label><label>Capas GPU (-1 automática)<input id="engine-gpu-layers" type="number" min="-1" max="999" value="${selected?.profile?.gpu_layers??-1}"></label><label>Batch lógico<input id="engine-batch" type="number" min="32" max="8192" value="${selected?.profile?.batch||256}"></label><label>Microbatch físico<input id="engine-ubatch" type="number" min="16" max="8192" value="${selected?.profile?.ubatch||128}"></label><label>Mapeo de pesos<select id="engine-mmap"><option value="yes">mmap · compartir páginas con macOS</option><option value="no">Sin mmap · más memoria privada</option></select></label>`:kind==='vllm'?`<label>Tokens por batch de prefill<input id="engine-batch" type="number" min="64" max="8192" value="${selected?.profile?.batch||256}"></label><p class="small">Secuencias simultáneas: 1. KV explícita calculada para el contexto, caché de prefijos desactivada.</p>`:`<label>Prioridad de prefill<select id="engine-priority"><option value="context">Contexto máximo · pasos adaptativos</option><option value="speed">Velocidad de prefill</option></select></label><p class="small">Una solicitud, prefill por bloques y caché SSD/RAM adicional desactivada.</p>`}</div></details><p class="small" id="model-description">${selected?esc(selected.compatibility||'GGUF de modelo principal. La carga debe confirmar el soporte de esta arquitectura.'):'Selecciona un modelo del desplegable.'}</p>
 <div id="moe-panel"></div><div class="inline"><button id="start-engine" class="primary" ${engine.running||!selected?'disabled':''}>Cargar modelo e iniciar</button><button id="stop-engine" ${engine.running?'':'disabled'}>Parar modelo y servidor</button><button id="engine-refresh">↻ Estado y modelos</button></div>
 <p class="small">Carpetas compartidas: ${catalog.roots.map(esc).join(' · ')}. Se excluyen ${catalog.excluded} entradas incompatibles o auxiliares. Puedes editar las carpetas en Modelos.</p>
 <p class="small">${kind==='llama'?'Flash Attention, una sesión y caché RAM de sesiones desactivada.':kind==='vllm'?'vLLM Metal real: una secuencia, prefill de 256 tokens, KV explícita por contexto y caché de prefijos desactivada. El presupuesto incluye pesos, KV y reserva.':'oMLX real: una solicitud, base de datos independiente, un solo modelo visible, cachés SSD y RAM desactivadas y guardia de memoria. Los tipos KV de llama.cpp no se trasladan como si fueran equivalentes.'} Al cerrar la ventana se liberan los procesos propios.</p></div>
 <div class="info-box">RAM libre: ${res.free_mb!==undefined?(res.free_mb/1024).toFixed(2)+' GB':'—'} · caché potencialmente reutilizable: ${res.reclaimable_cache_mb!==undefined?(res.reclaimable_cache_mb/1024).toFixed(2)+' GB':'—'} · comprimida: ${res.compressed_mb!==undefined?(res.compressed_mb/1024).toFixed(2)+' GB':'—'}. La limpieza actúa sobre recursos propios; no termina procesos del sistema ni de otras apps.</div><div class="card"><h3>Cómo se aprovecha el contexto</h3><p>El historial íntegro queda en SQLite. El agente consulta fragmentos, reserva tokens de salida y compacta el historial con el mismo modelo. llama.cpp permite contar con su tokenizador; otros motores muestran una estimación conservadora. El presupuesto del chat no amplía el contexto del servidor.</p></div>`;
 updateMoePanel(selected,kind);if(selected?.profile?.kv)$('#engine-kv').value=selected.profile.kv;if($('#engine-mmap'))$('#engine-mmap').value=selected?.profile?.mmap===false?'no':'yes';if($('#engine-cpu'))$('#engine-cpu').value=selected?.profile?.cpu?'cpu':'gpu';if($('#engine-priority'))$('#engine-priority').value=selected?.profile?.prefill_priority||'context';if(engine.engine===kind&&kind==='llama'&&engine.kv)$('#engine-kv').value=engine.kv;
 on('#engine-kind','change',async()=>{const next=$('#engine-kind').value;await persistEngineProfile(kind);localStorage.setItem('engine-kind',next);await renderEngine(next);});
 on('#engine-model-select','change',async()=>{const m=catalog.models.find(m=>m.path===$('#engine-model-select').value);$('#engine-model').value=m?.path||'';$('#engine-context').value=m?.context||4096;$('#start-engine').disabled=engine.running||!m;$('#model-description').textContent=m?.compatibility||(m?'GGUF de modelo principal; verifica la carga de su arquitectura.':'Selecciona un modelo.');updateMoePanel(m,kind);if(m){localStorage.setItem('engine-model:'+kind,m.path);const p=m.profile||{};if(p.kv)$('#engine-kv').value=p.kv;if($('#engine-memory'))$('#engine-memory').value=p.memory_gb||8;for(const [id,key,fallback] of [['#engine-threads','threads',8],['#engine-batch','batch',256],['#engine-ubatch','ubatch',128],['#engine-gpu-layers','gpu_layers',-1]])if($(id))$(id).value=p[key]??fallback;if($('#engine-mmap'))$('#engine-mmap').value=p.mmap===false?'no':'yes';if($('#engine-priority'))$('#engine-priority').value=p.prefill_priority||'context';await persistEngineProfile(kind);}});
 for(const input of document.querySelectorAll('#engine-tab input,#engine-tab select'))if(!['engine-kind','engine-model-select'].includes(input.id))input.addEventListener('change',()=>persistEngineProfile(kind).catch(e=>toast(e.message)));
 on('#engine-refresh','click',async()=>{await persistEngineProfile(kind);await renderEngine(kind);});
 on('#stop-engine','click',async()=>{await api('/api/engine/stop',{});await refresh();await renderEngine(kind);await refreshModels();});
 on('#start-engine','click',async()=>{const model=$('#engine-model').value,context=+$('#engine-context').value,kv=$('#engine-kv').value,binary=$('#engine-binary')?.value,memory_gb=+($('#engine-memory')?.value||8);if(!model)throw Error('Selecciona un modelo compatible.');if(!confirm(`¿Cargar este modelo con ${names[kind]}?\n${model}\nContexto: ${context.toLocaleString()} · KV: ${kv}\nLos pesos y la caché ocuparán memoria unificada.`))return;localStorage.setItem('engine-model:'+kind,model);localStorage.setItem('engine-kind',kind);if(binary)localStorage.setItem('engine-binary',binary);await api('/api/engine/start',{engine:kind,binary,model,context,kv,memory_gb,threads:+($('#engine-threads')?.value||8),batch:+($('#engine-batch')?.value||256),ubatch:+($('#engine-ubatch')?.value||128),gpu_layers:+($('#engine-gpu-layers')?.value??-1),mmap:$('#engine-mmap')?.value!=='no',prefill_priority:$('#engine-priority')?.value||'context',moe_cpu_layers:+($('#moe-cpu-layers')?.value||0),moe_cache_mib:+($('#moe-cache')?.value||0),moe_offload:$('#moe-offload')?.checked||false,moe_fraction:+($('#moe-fraction')?.value||.25),cpu:$('#engine-cpu')?.value==='cpu',confirm_load:true});await refresh();$('#provider').value='own';await renderEngine(kind);toast('Motor iniciado. Consulta el estado hasta que esté listo.');});
}
function renderSkills(){$('#skills-tab').innerHTML=pageTop('COMPORTAMIENTO REUTILIZABLE','Habilidades a tu medida.','Instrucciones locales, editables y activables. Se añaden al contexto de tus conversaciones. No instalan código ni herramientas externas.', '<button id="new-skill" class="primary">＋ Nueva habilidad</button>')+`<div class="card-grid">${state.skills.map(s=>`<div class="card"><div class="inline"><h3>${esc(s.name)}</h3><span class="spacer"></span><button data-toggle-skill="${esc(s.id)}" class="chip ${s.enabled?'':'off'}">${s.enabled?'Activa':'Desactivada'}</button></div><p>${esc(s.content.slice(0,350))}</p><button data-edit-skill="${esc(s.id)}">Editar</button> <button data-delete-skill="${esc(s.id)}" class="danger">Eliminar</button></div>`).join('')}</div>`;on('#new-skill','click',()=>openEditor('Nueva habilidad','','','Solo se activará el texto que guardes.',async(name,content)=>{await api('/api/skills',{name,content,enabled:true});await refresh();renderSkills();}));}
on('#skills-tab','click',async e=>{const b=e.target.closest('[data-toggle-skill],[data-edit-skill],[data-delete-skill]');if(!b)return;const id=b.dataset.toggleSkill||b.dataset.editSkill||b.dataset.deleteSkill,s=state.skills.find(s=>s.id===id);if(b.dataset.editSkill){openEditor('Editar habilidad',s.name,s.content,'El texto activo ocupa espacio en el contexto.',async(name,content)=>{await api('/api/skills',{...s,name,content});await refresh();renderSkills();});return;}if(b.dataset.deleteSkill){if(!confirm('¿Eliminar esta habilidad?'))return;await api('/api/skills/delete',{id});}else await api('/api/skills',{...s,enabled:!s.enabled});await refresh();renderSkills();});
function renderConnections(){$('#connections-tab').innerHTML=pageTop('PUENTES LOCALES','Tus motores, conectados.','Conecta servidores compatibles con OpenAI a través de loopback. La app consulta sus modelos y envía inferencias; no inicia, detiene ni reconfigura esos servidores.')+`<div class="card"><h3>Proveedores</h3><p>Un proveedor por línea: identificador | nombre | URL. Conserva «own» para el motor propio.</p><textarea id="provider-config" rows="7">${esc(state.providers.map(p=>`${p.id} | ${p.name} | ${p.url}`).join('\n'))}</textarea><button id="save-providers" class="primary">Guardar conexiones</button></div><div class="card"><h3>API para desarrollo</h3><p>Esta misma app ofrece <code>/v1/models</code> y <code>/v1/chat/completions</code>, dirigidos al proveedor seleccionado en Conversación. Requieren la sesión local o un token Bearer. El lanzador CLI admite un token mediante la variable AGENTIC_STUDIO_TOKEN.</p><pre class="code">GET  http://127.0.0.1:${location.port}/v1/models\nPOST http://127.0.0.1:${location.port}/v1/chat/completions</pre><p class="small">MCP local por stdio y navegador privado se configuran por proyecto mediante «MCP y navegador». OAuth de MCP está en «MCP y navegador»; OpenAI OAuth se configura arriba. LM Link y correo siguen pendientes.</p></div>`;$('#connections-tab').insertAdjacentHTML('afterbegin',openAIControls()+lanControls());wireOpenAI();wireLAN();on('#save-providers','click',async()=>{const providers=$('#provider-config').value.split('\n').filter(s=>s.trim()).map(line=>{const [id,name,url]=line.split('|').map(s=>s.trim());if(!id||!name||!url)throw Error('Formato: id | nombre | URL');return{id,name,url};});await api('/api/providers',{providers});await refresh();renderProviders();await refreshModels();toast('Conexiones guardadas.');});}
async function renderActivity(){const rows=await api('/api/audit');$('#activity-tab').innerHTML=pageTop('TRAZABILIDAD','Cada acción deja rastro.','Herramientas usadas, propuestas revisadas y cambios en archivos. El historial de conversaciones y las memorias operativas se guardan por separado.')+`<table><thead><tr><th>FECHA</th><th>ACCIÓN</th><th>DETALLE</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(new Date(r.created*1000).toLocaleString('es-ES'))}</td><td><span class="chip">${esc(r.action)}</span></td><td class="small">${esc(r.detail)}</td></tr>`).join('')}</tbody></table>`;}
async function updateResources(){try{const r=await api('/api/resources');$('#resource-mini').textContent=`Backend ${r.app_rss_mb??'—'} MB${r.engine_rss_mb?' · motor '+r.engine_rss_mb+' MB':''}${r.openai_rss_mb?' · OpenAI '+r.openai_rss_mb+' MB':''}${r.free_mb!==undefined?' · libre '+(r.free_mb/1024).toFixed(1)+' GB':''}`;}catch{}}
async function init(){try{await refresh();currentProject=state.workspace?.project||currentProject;currentSession=state.workspace?.session||currentSession;bootstrapping=false;renderSidebar();await loadInspector();renderProviders();await refreshModels();await loadMessages();await updateResources();setInterval(updateResources,15000);}catch(e){toast(e.message);$('#agent-status').textContent='Abre Agentic Studio desde su aplicación o lanzador para autenticar la sesión local.';}}
init();

let workspaceProject='';
on('#workspace-settings','click',()=>{const p=state.projects.find(p=>p.id===currentProject);if(!p)return;workspaceProject=p.id;const cfg=p.config||{};$('#workspace-root').value=cfg.root||'';$('#workspace-write').value=cfg.write||'review';$('#workspace-execute').value=cfg.execute||'review';$('#workspace-dialog').showModal();});
on('#workspace-close','click',()=>$('#workspace-dialog').close());
on('#workspace-choose','click',()=>{if(window.webkit?.messageHandlers?.studio)window.webkit.messageHandlers.studio.postMessage({action:'chooseFolder',project:workspaceProject});else{$('#workspace-root').focus();toast('Introduce la ruta absoluta de la carpeta autorizada.');}});
window.studioFolderSelected=data=>{if(data.project===workspaceProject&&$('#workspace-dialog').open)$('#workspace-root').value=data.path;};
on('#workspace-form','submit',async e=>{e.preventDefault();const write=$('#workspace-write').value,execute=$('#workspace-execute').value;if(execute==='allow'&&!confirm('¿Permitir comandos automáticos dentro de la carpeta autorizada, con el aislamiento de macOS?'))return;await api('/api/project-config',{project:workspaceProject,root:$('#workspace-root').value,write,execute});$('#workspace-dialog').close();await refresh();toast('Carpeta y permisos guardados para este proyecto.');});

let pollingCommands=false;
setInterval(async()=>{if(pollingCommands||!currentSession||(!busy&&!commandResolving))return;pollingCommands=true;try{const rows=await api('/api/command-live?session='+encodeURIComponent(currentSession));for(const item of rows){const old=commandOffsets[item.id]||0;if(item.bytes>old){const delta=item.bytes-old;logActivity('Terminal en directo · '+item.output.slice(-Math.min(delta,item.output.length)));commandOffsets[item.id]=item.bytes;}}}catch{}finally{pollingCommands=false;}},750);

let extensionProject='';
function extensionDraft(){const mcp=JSON.parse($('#extension-mcp').value||'[]');if(!Array.isArray(mcp))throw Error('MCP debe ser una lista JSON.');return{project:extensionProject,mcp,browser:{origins:$('#extension-origins').value.split('\n').map(s=>s.trim()).filter(Boolean),read:$('#extension-read').value,act:$('#extension-act').value}};}
function extensionServers(){let list;try{list=extensionDraft().mcp;}catch{return;}const previous=$('#extension-server').value;$('#extension-server').innerHTML=list.map(s=>`<option value="${esc(s.id)}">${esc(s.id)}</option>`).join('');if(list.some(s=>s.id===previous))$('#extension-server').value=previous;}
on('#extension-settings','click',async()=>{if(!currentProject)return;extensionProject=currentProject;const data=await api('/api/extensions?project='+encodeURIComponent(extensionProject));$('#extension-mcp').value=JSON.stringify(data.config.mcp,null,2);$('#extension-origins').value=data.config.browser.origins.join('\n');$('#extension-read').value=data.config.browser.read;$('#extension-act').value=data.config.browser.act;$('#extension-status').textContent=(data.browser_available?'Puente de navegador nativo conectado.':'Abre la app macOS para usar el navegador.')+' Un servidor MCP activo como máximo; no se cargan modelos auxiliares.';$('#extension-tools').textContent='';extensionServers();$('#extension-dialog').showModal();});
on('#extension-close','click',()=>$('#extension-dialog').close());
on('#extension-mcp','change',extensionServers);
on('#extension-form','submit',async e=>{e.preventDefault();await api('/api/extensions',extensionDraft());$('#extension-dialog').close();logActivity('Configuración MCP/navegador guardada; conexiones anteriores liberadas.');toast('Permisos de MCP y navegador guardados para este proyecto.');});
on('#extension-stop','click',async()=>{await api('/api/extensions/stop',{});logActivity('MCP desconectado y navegador cerrado.');toast('Conexiones liberadas.');});
on('#extension-discover','click',async()=>{const draft=extensionDraft(),server=draft.mcp.find(s=>s.id===$('#extension-server').value);if(!server)throw Error('Configura un servidor MCP.');if(!confirm('¿Guardar esta configuración y conectar este servidor MCP?\n'+JSON.stringify(server.transport==='http'?{url:server.url}:{command:server.command,args:server.args},null,2)))return;await api('/api/extensions',draft);$('#extension-status').textContent='Conectando y negociando MCP…';const data=await api('/api/extensions/discover',{project:extensionProject,server:server.id,approve:true});$('#extension-status').textContent=`MCP conectado · ${data.transport==='http'?'HTTP remoto':'PID '+data.pid} · ${data.tools.length} herramientas reales`;$('#extension-tools').innerHTML=data.tools.map((tool,index)=>`<div class="extension-tool"><b>${esc(tool.name)}</b><p class="small">${esc((tool.description||'').slice(0,500))}</p><label>Permiso<select data-mcp-permission="${index}">${[['deny','Denegado'],['review','Pedir revisión'],['allow','Permitido']].map(([value,label])=>`<option value="${value}" ${(server.tools?.[tool.name]||'deny')===value?'selected':''}>${label}</option>`).join('')}</select></label>${server.transport==='http'?`<label><input type="checkbox" data-mcp-read="${index}" ${(server.read_only_tools||[]).includes(tool.name)?'checked':''}> Declaro que esta herramienta solo lee datos y carece de efectos externos</label>`:''}<details><summary>Esquema de argumentos</summary><pre>${esc(JSON.stringify(tool.inputSchema||{},null,2))}</pre></details></div>`).join('');for(const select of $('#extension-tools').querySelectorAll('[data-mcp-permission]'))select.addEventListener('change',()=>{const value=extensionDraft();const target=value.mcp.find(s=>s.id===server.id);target.tools=target.tools||{};target.tools[data.tools[+select.dataset.mcpPermission].name]=select.value;$('#extension-mcp').value=JSON.stringify(value.mcp,null,2);});logActivity(`MCP ${server.id}: ${data.tools.length} herramientas descubiertas; las nuevas siguen denegadas hasta que guardes su permiso.`);});

on('#extension-add-remote','click',()=>{const url=prompt('Endpoint MCP remoto HTTPS (ejemplo: https://servidor.example/mcp)');if(!url)return;const id=prompt('Identificador único del servidor','remoto');if(!id)return;const draft=extensionDraft();draft.mcp.push({id,transport:'http',url,tools:{},read_only_tools:[]});$('#extension-mcp').value=JSON.stringify(draft.mcp,null,2);extensionServers();});
$('#extension-tools').addEventListener('change',e=>{const el=e.target;if(!el.matches('[data-mcp-read]'))return;const draft=extensionDraft(),server=draft.mcp.find(s=>s.id===$('#extension-server').value),tool=$('#extension-tools').querySelectorAll('.extension-tool b')[+el.dataset.mcpRead]?.textContent;if(!server||!tool)return;server.read_only_tools=(server.read_only_tools||[]).filter(t=>t!==tool);if(el.checked)server.read_only_tools.push(tool);$('#extension-mcp').value=JSON.stringify(draft.mcp,null,2);});
function oauthTarget(){const server=extensionDraft().mcp.find(s=>s.id===$('#extension-server').value);if(server?.transport!=='http')throw Error('Selecciona un MCP HTTP remoto y guarda su configuración.');return{project:extensionProject,server:server.id};}
on('#oauth-status','click',async()=>{const data=await api('/api/oauth/status',oauthTarget());$('#extension-status').textContent=data.connected?'OAuth conectado · scopes: '+(data.scopes.join(', ')||'(sin scope explícito)')+' · caduca '+new Date(data.expires_at*1000).toLocaleString():'Sin credenciales OAuth para esta configuración del proyecto.';});
on('#oauth-forget','click',async()=>{const target=oauthTarget();if(!confirm('¿Desconectar MCP y eliminar del llavero las credenciales de este servidor y proyecto?'))return;await api('/api/oauth/forget',target);$('#extension-status').textContent='Credenciales eliminadas. La revocación en el proveedor se gestiona desde tu cuenta.';});
on('#oauth-connect','click',async()=>{const target=oauthTarget();await api('/api/extensions',extensionDraft());$('#extension-status').textContent='Consultando metadatos del recurso OAuth…';const prepared=await api('/api/oauth/prepare',target);const issuer=prepared.issuers.length===1?prepared.issuers[0]:prompt('Selecciona un issuer anunciado:\n'+prepared.issuers.join('\n'),prepared.issuers[0]);if(!issuer||!prepared.issuers.includes(issuer))return;if(!confirm('¿Consultar este proveedor OAuth?\n'+issuer+'\nRecurso: '+prepared.resource))return;const metadata=await api('/api/oauth/metadata',{...target,id:prepared.id,issuer,approve:true});const scopes=prompt('Scopes solicitados (separados por espacios; usa los mínimos necesarios):',prepared.default_scopes.join(' '));if(scopes===null)return;const client_id=prompt('Client ID público registrado. Déjalo vacío para registro dinámico si el proveedor lo ofrece.','');if(client_id===null)return;if(!confirm('¿Autorizar OAuth en el navegador del sistema?\n'+JSON.stringify(metadata,null,2)+'\nScopes solicitados: '+scopes+'\nCliente: '+(client_id||'registro dinámico público')) )return;await api('/api/oauth/start',{...target,id:prepared.id,client_id,scopes:scopes.trim().split(/\s+/).filter(Boolean),approve:true});$('#extension-status').textContent='Completa OAuth en el navegador. Después pulsa Estado OAuth y Conectar y descubrir herramientas. Las herramientas siguen sujetas a permisos del proyecto.';});

on('#extension-server','change',()=>{$('#extension-tools').textContent='Selecciona Conectar y descubrir herramientas para revisar este servidor.';});

let hubSelection=null,hubTimer=null;
async function renderHub(){const el=$('#hub-panel');if(!el)return;el.innerHTML=`<h2>Hugging Face · descubrir y descargar</h2><p>Últimos modelos actualizados por defecto. Destino: <b>/path/to/storage/models</b>. Las descargas no cargan pesos en RAM.</p><div class="inline"><input id="hub-query" placeholder="Buscar modelos, autor o nombre"><select id="hub-kind"><option value="">Todos los formatos</option><option value="gguf">GGUF</option><option value="mlx">MLX</option></select><select id="hub-sort"><option value="lastModified">Últimos actualizados</option><option value="createdAt">Últimos publicados</option><option value="downloads">Más descargados</option><option value="likes">Más valorados</option></select><button id="hub-search">Buscar</button></div><div id="hub-results"></div><div id="hub-files"></div><p id="hub-progress" role="status"></p><button id="hub-cancel">Cancelar descarga</button><p class="small">Solo archivos públicos. Para MLX selecciona todos los shards de pesos y su configuración/tokenizador. Un GGUF dividido necesita todas sus partes. Se fija la revisión, se verifica el hash y se conservan los parciales al cancelar para reanudar. No se sobrescriben archivos diferentes.</p>`;on('#hub-search','click',searchHub);on('#hub-query','keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchHub().catch(e=>toast(e.message));}});on('#hub-cancel','click',async()=>{await api('/api/hub/cancel',{});await hubProgress();});await searchHub();if(!hubTimer)hubTimer=setInterval(()=>{if(currentTab==='models')hubProgress().catch(()=>{});},2000);await hubProgress();}
async function searchHub(){const box=$('#hub-results');box.textContent='Consultando Hugging Face…';const data=await api('/api/hub/search?q='+encodeURIComponent($('#hub-query').value)+'&kind='+$('#hub-kind').value+'&sort='+$('#hub-sort').value);box.innerHTML=data.models.map((m,i)=>`<div class="file-row"><b>${esc(m.id)}</b><small>${esc(m.modified||'')} · ${m.downloads} descargas</small><button data-hub-repo="${i}">Ver archivos y tamaño</button></div>`).join('')||'<p>Sin resultados.</p>';for(const btn of box.querySelectorAll('[data-hub-repo]'))btn.addEventListener('click',()=>hubFiles(data.models[+btn.dataset.hubRepo].id).catch(e=>toast(e.message)));}
async function hubFiles(repo){hubSelection=await api('/api/hub/files?repo='+encodeURIComponent(repo));const box=$('#hub-files');box.innerHTML=`<h3>${esc(repo)}</h3><p>Revisión ${esc(hubSelection.commit.slice(0,12))}</p><button id="hub-all-mlx">Seleccionar MLX completo</button><div style="max-height:320px;overflow:auto">${hubSelection.files.map((f,i)=>`<label><input type="checkbox" data-hub-file="${i}" ${f.kind==='config'?'checked':''}>${esc(f.name)} · ${bytes(f.size)}</label>`).join('')}</div><button id="hub-download" class="primary">Descargar selección</button>`;on('#hub-all-mlx','click',()=>{for(const c of box.querySelectorAll('[data-hub-file]'))c.checked=hubSelection.files[+c.dataset.hubFile].kind!=='gguf';});on('#hub-download','click',async()=>{const selected=[...box.querySelectorAll('[data-hub-file]:checked')].map(c=>hubSelection.files[+c.dataset.hubFile]);if(!selected.length)throw Error('Selecciona al menos un archivo.');if(!confirm('¿Descargar '+selected.length+' archivos ('+bytes(selected.reduce((s,f)=>s+f.size,0))+') en /path/to/storage/models?\n'+selected.map(f=>f.name).join('\n')))return;await api('/api/hub/start',{repo:hubSelection.repo,files:selected.map(f=>f.name),approve:true});await hubProgress();});}
async function hubProgress(){const el=$('#hub-progress');if(!el)return;const d=await api('/api/hub/status');el.textContent=d.status==='idle'?'Sin descargas activas.':`${d.status} · ${d.file||''} · ${bytes(d.done||0)} / ${bytes(d.total||0)}${d.error?' · '+d.error:''}${d.destination?' · '+d.destination:''}`;}
function openAIControls(){return `<div class="card"><h2>OpenAI · iniciar sesión con ChatGPT</h2><p>Usa el adaptador oficial Codex con OAuth y tu cuenta ChatGPT. Los modelos disponibles dependen de tu cuenta. La conversación y los fragmentos de archivos que selecciones se envían a OpenAI; las herramientas se ejecutan en Agentic bajo los permisos del proyecto.</p><button id="openai-login" class="primary">Conectar OpenAI con OAuth</button><button id="openai-status">Estado</button><button id="openai-logout">Cerrar sesión OpenAI</button><button id="openai-release">Liberar adaptador</button><p id="openai-info" role="status">No se inicia ningún modelo local adicional. Muestreo y ventana real dependen del modelo de OpenAI; la longitud solicitada es orientativa y el adaptador limita el texto recibido.</p></div>`;}
function wireOpenAI(){on('#openai-login','click',async()=>{if(!currentProject)throw Error('Selecciona un proyecto.');await api('/api/openai/login',{project:currentProject});$('#openai-info').textContent='Completa el inicio de sesión oficial en el navegador. Después consulta Estado y elige OpenAI en Conversación.';});on('#openai-status','click',async()=>{const s=await api('/api/openai/status');$('#openai-info').textContent=s.connected?'OpenAI conectado · '+s.auth_mode:s.login_pending?'Inicio de sesión pendiente en el navegador.':s.login_error||'Sin cuenta conectada.';});on('#openai-logout','click',async()=>{await api('/api/openai/logout',{});$('#openai-info').textContent='Sesión de Agentic cerrada; las sesiones de otras apps se conservan.';});on('#openai-release','click',async()=>{await api('/api/openai/stop',{});$('#openai-info').textContent='Adaptador liberado. La credencial permanece en su llavero aislado.';});}
function lanControls(){return `<div class="card"><h2>iPhone / iPad · red local</h2><p>El móvil usa el modelo del Mac. Vinculación de un solo proyecto, TLS con huella del certificado y revisión de sus acciones. El Mac debe permanecer abierto y ambos dispositivos en la misma red.</p><button id="lan-start" class="primary">Activar y vincular este proyecto…</button><button id="lan-status">Estado de red local</button><button id="lan-stop">Desactivar y revocar móviles</button><p id="lan-info" role="status"></p></div>`;}
function wireLAN(){on('#lan-start','click',async()=>{if(!currentProject)throw Error('Selecciona un proyecto.');const d=await api('/api/lan/start',{project:currentProject,approve:true});$('#lan-info').textContent='Servidor local activo: '+d.url+' · vinculación válida cinco minutos.';if(window.webkit?.messageHandlers?.studio)window.webkit.messageHandlers.studio.postMessage({action:'shareLAN',url:d.pair_url});else $('#lan-info').textContent+=' Abre la app macOS para mostrar el QR.';});on('#lan-status','click',async()=>{const d=await api('/api/lan/status');$('#lan-info').textContent=d.running?`Activo · ${d.url} · ${d.clients} clientes · proyecto ${d.project}`:'Red local desactivada.';});on('#lan-stop','click',async()=>{await api('/api/lan/stop',{});$('#lan-info').textContent='Servidor detenido y vinculaciones revocadas.';});}
